import math

def E(a):
    # E(a) = a * floor(22*a * floor(22*a))
    term1 = 22 * a
    floor_term = math.floor(term1)
    term2 = 22 * a * floor_term
    return a * math.floor(term2)

# Test values of a in the range (0, 1) with step size 0.01
results = {}
step = 0.01
for i in range(1, 101): # i = 1 to 100, corresponding to a = 0.01 to 1.00
    a = i * step
    if a == 0:
        continue

    try:
        e_a = E(a)
        results[a] = e_a
    except OverflowError:
        results[a] = float('inf')

# Check for values close to 4
solutions_candidates = {}
tolerance = 1e-3 # Numerical tolerance
for a, e_a in results.items():
    if abs(e_a - 4) < tolerance:
        solutions_candidates[a] = e_a

print("--- Numerical Test Results ---")
print(f"Number of candidates found near 4: {len(solutions_candidates)}")
if solutions_candidates:
    print("Candidates (a, E(a)):")
    for a, e_a in solutions_candidates.items():
        print(f"a = {a:.2f}, E(a) = {e_a}")
else:
    print("No candidates found near 4 with step 0.01.")

